<template><div><div class="page-head"><h2>管理员</h2><el-button type="primary" @click="open()">新增管理员</el-button></div><el-table :data="items" border><el-table-column prop="username" label="账号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="role_name" label="角色"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="s"><el-button link type="primary" @click="open(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="form.id?'编辑管理员':'新增管理员'"><el-form label-width="80px"><el-form-item label="账号"><el-input v-model="form.username" :disabled="!!form.id"/></el-form-item><el-form-item label="姓名"><el-input v-model="form.name"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" placeholder="编辑时留空则不修改"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role_id"><el-option v-for="r in roles" :key="r.id" :label="r.name" :value="r.id"/></el-select></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessageBox}from'element-plus';import{createAdmin,deleteAdmin,getAdmins,getRoles,updateAdmin}from'@/api';import type{Admin,Role}from'@/types';const items=ref<Admin[]>([]),roles=ref<Role[]>([]),visible=ref(false),form=reactive({id:0,username:'',name:'',password:'',role_id:0,enabled:true});async function load(){items.value=(await getAdmins()).data;roles.value=(await getRoles()).data}function open(item?:Admin){Object.assign(form,item?{...item,password:''}:{id:0,username:'',name:'',password:'',role_id:roles.value[0]?.id||0,enabled:true});visible.value=true}async function save(){const data={username:form.username,name:form.name,password:form.password,role_id:form.role_id,enabled:form.enabled};if(form.id){await updateAdmin(form.id,data)}else{await createAdmin(data)}visible.value=false;await load()}async function remove(id:number){await ElMessageBox.confirm('确认删除该管理员？');await deleteAdmin(id);await load()}onMounted(load);</script>
